% DIFFERENTIATORS BUILT AS  DELAY + WEIGHTED SUBTRACTION  (paper Eqs. (2) and (8))
%
% Block 0 (adapter), unchanged:  EV signal --> ... --> UMP = m_in
%
% Each differentiator makes two "rails" that cancel one-for-one:
%   direct rail    x --r_F--> P,              P --> removed with rate constant k_r
%   delayed rail   x --r_S--> M --r_Sr--> N,  N --> removed with the SAME k_r
%   canceler       P + N --r_I--> products
% M is the delay (time constant tau_d = 1/k_Sr). Because both rails lose the
% same k_r and the canceler takes one molecule of each,
%   P - N  =  w * ( x  -  x delayed by tau_d ),   smoothed with 1/k_r,   w = k_F/k_r,
% whatever the strength of r_I. With a strong r_I only one rail survives:
% P when x rises, N when x falls. At rest both are near zero.
%
% Differentiator 1:  x = m_in,  M = m_S,  P = m_F,  N = m_d1  (output: it rises
%   while m_in FALLS = inverted polarity). The k_r of m_F is r_Fr. The k_r of
%   m_d1 is the LOAD: r_F_2 and r_S_2 of differentiator 2 consume m_d1.
% Differentiator 2:  x = m_d1,  M = m_S2,  P = m_F2 = m_d2 (output: rises while
%   m_d1 rises),  N = m_N2. The k_r of m_F2 is r_Fr_2. m_N2 needs a removal of
%   its own with the same k_r: a SIXTH reaction, r_Nr_2, not in the workbook
%   (the constants of r_Fr_2 are used for it).
% Counter, as before: r_c and r_I2 are activated by m_d2 (not consumed).
%
% Kinetics: every differentiator reaction is first order, rate = k*m with
% k = kcat*[E]/K_M (enzyme far from saturation); r_I is second order,
% rate = k_I*P*N with k_I = kcat*[E]/(K_M*K_M). Section 7 prints how far each
% pool is from its K_M. Block 0 and the counter keep Michaelis-Menten rates.
% Only the analysed distance (row) is simulated, from the rest state.
%
% Needs Parameters.m, Dataset_cell2cell.mat and kinetics_BRENDA.xlsx.
clc;
% clearvars;
close all;

addingPathParentFolderByName('code'); %[output:5fd1c808]
Parameters                               % provides dt0 and fontsize
%%
%[text] ## 1. Input data
% load Dataset_cell2cell.mat
Dataset  = rmmissing(Dataset);
dist     = table2array(Dataset(:,1));
vesicles = table2array(Dataset(:,2:end));

row = 1;                                 % distance analysed in detail
N = size(vesicles,2);
t = (0:N-1)'*dt0;
assert(N >= 3 && all(isfinite(vesicles(row,:))) && all(vesicles(row,:) >= 0) && vesicles(row,1) > 0, ...
    'Use a finite nonnegative EV signal with a positive first sample.');
%%
%[text] ## 2. Enzyme constants from the BRENDA workbook
% Sheet "values" of kinetics_BRENDA.xlsx: reaction label in column B, and the
% columns K_M [mM], SA [umol/min/mg] and MW [mg/umol] found by their titles.
% kcat [1/s] = SA*MW/60.
raw = readcell('kinetics_BRENDA.xlsx','Sheet','values');
isText = @(x) ischar(x) || (isstring(x) && isscalar(x) && ~ismissing(x));
hdrRow = find(any(cellfun(@(x) isText(x) && startsWith(string(x),"K_M"),raw),2),1);
assert(~isempty(hdrRow),'Header row (a cell starting with "K_M") not found in the workbook.');
colOf = @(title) find(cellfun(@(x) isText(x) && startsWith(string(x),title),raw(hdrRow,:)),1);
colKM = colOf("K_M");  colSA = colOf("SA");  colMW = colOf("MW");

reactionNames = {'r_S','r_Sr','r_F','r_Fr','r_I'};

KM = nan(1,5);  kcat = nan(1,5);
for i = 1:5
    r = find(cellfun(@(x) isText(x) && strcmp(strtrim(char(x)),reactionNames{i}),raw(:,2)),1);
    assert(~isempty(r),'Reaction %s not found in column B of the workbook.',reactionNames{i});
    KM(i)   = raw{r,colKM};
    kcat(i) = raw{r,colSA}*raw{r,colMW}/60;
end
assert(all(isfinite([KM kcat])) && all([KM kcat] > 0),'K_M, SA and MW of the five reactions must be positive numbers.');

KM_S  = KM(1);  kcat_S  = kcat(1);       % r_S :  m_in -> m_S
KM_Sr = KM(2);  kcat_Sr = kcat(2);       % r_Sr:  m_S  -> m_d1
KM_F  = KM(3);  kcat_F  = kcat(3);       % r_F :  m_in -> m_F
KM_Fr = KM(4);  kcat_Fr = kcat(4);       % r_Fr:  m_F  -> products
KM_I  = KM(5);  kcat_I  = kcat(5);       % r_I :  m_F + m_d1 -> products (K_M used for both substrates: assumed)

reactionNames2 = {'r_S_2','r_Sr_2','r_F_2','r_Fr_2','r_I_2'};
KM2 = nan(1,5);  kcat2 = nan(1,5);
for i = 1:5
    r = find(cellfun(@(x) isText(x) && strcmp(strtrim(char(x)),reactionNames2{i}),raw(:,2)),1);
    assert(~isempty(r),'Reaction %s not found in column B of the workbook.',reactionNames2{i});
    KM2(i)   = raw{r,colKM};
    kcat2(i) = raw{r,colSA}*raw{r,colMW}/60;
end
KM_S_2  = KM2(1);  kcat_S_2  = kcat2(1);   % r_S_2 : m_d1 -> m_S2
KM_Sr_2 = KM2(2);  kcat_Sr_2 = kcat2(2);   % r_Sr_2: m_S2 -> m_N2
KM_F_2  = KM2(3);  kcat_F_2  = kcat2(3);   % r_F_2 : m_d1 -> m_F2 = m_d2
KM_Fr_2 = KM2(4);  kcat_Fr_2 = kcat2(4);   % r_Fr_2: m_F2 -> products
KM_I_2  = KM2(5);  kcat_I_2  = kcat2(5);   % r_I_2 : m_F2 + m_N2 -> products (K_M for both: assumed)

reactionNamesC = {'r_Cp','r_Cg','r_Cr'};
KMC = nan(1,3);  kcatC = nan(1,3);
for i = 1:3
    r = find(cellfun(@(x) isText(x) && strcmp(strtrim(char(x)),reactionNamesC{i}),raw(:,2)),1);
    assert(~isempty(r),'Reaction %s not found in column B of the workbook.',reactionNamesC{i});
    KMC(i)   = raw{r,colKM};
    kcatC(i) = raw{r,colSA}*raw{r,colMW}/60;
end
assert(all(isfinite([KM2 kcat2 KMC kcatC])) && all([KM2 kcat2 KMC kcatC] > 0),'K_M, SA and MW must be positive numbers.');
KM_Cp   = KMC(1);  kcat_Cp = kcatC(1);   % r_c  = r_Cp: buffered substrate -> m_c, activated by m_d2
KM_Cg_c = KMC(2);  kcat_Cg = kcatC(2);   % r_I1 = r_Cg: m_c + m_I -> products;   K_M for m_c
KM_Cg_I = KMC(2);                        %               K_M for m_I: assumed equal
KM_Cr   = KMC(3);  kcat_Cr = kcatC(3);   % r_I2 = r_Cr: m_I -> products, activated by m_d2
%%
%[text] ## 3. Design choices
E_max = 0.02;                            % largest feasible enzyme concentration [mM] (20 uM)
m_in_target = 0.00125;                   % resting input level [mM]

% Differentiator 1
tau_d1 = 60;                             % delay of the delayed rail (pool m_S) [s]
tau_r1 = 30;                             % common removal time of the two rails m_F and m_d1 [s]
w_1    = 1;                              % gain: m_F - m_d1 = w_1*(m_in - delayed m_in)
% Differentiator 2
tau_d2 = 60;                             % delay (pool m_S2) [s]
tau_r2 = 30;                             % common removal time of m_F2 and m_N2 [s]
%                                          (its gain is fixed by the load: w_2 = tau_r2/(2*tau_r1))
% Canceler r_I and r_I_2
ideal_canceler = true;                   % true : strong enough to leave the rails at rest_1, rest_2
%                                          false: limited to E_max, to see what is feasible
rest_1 = 1e-7;                           % wanted resting level of m_F and m_d1 [mM] (ideal canceler)
rest_2 = 1e-8;                           % wanted resting level of m_F2 and m_N2 [mM] (ideal canceler)
% Counter
gate_factor   = 100;                     % K_gate = gate_factor * resting m_d2
count_step    = 0.01;                    % m_c gained if r_c ran fully activated for pulse_time [mM]
pulse_time    = 200;                     % nominal length of an m_d2 pulse [s]
tau_reset     = 600;                     % reset time constant of m_c [s]
m_I_base      = 2;                       % buffered level of m_I [mM] (illustrative)
tau_I_supply  = 60;                      % refill time of m_I [s]
%%
%[text] ## 4. Rate constants, rest state and enzyme concentrations
% ---- Differentiator 1 ----
k_r1 = 1/tau_r1;                         % removal of each rail
k_F  = w_1*k_r1;                         % m_in -> m_F
k_S  = k_F;                              % m_in -> m_S: the same flux into both rails
k_Sr = 1/tau_d1;                         % m_S -> m_d1
k_Fr = k_r1;                             % m_F -> products
k_F_2 = k_r1/2;  k_S_2 = k_r1/2;         % m_d1 -> m_F2 and m_d1 -> m_S2: together the k_r of m_d1
flux_1 = k_F*m_in_target;                % resting production of each rail [mM/s]
m_S_ref = k_S*m_in_target/k_Sr;
if ideal_canceler
    assert(k_r1*rest_1 < flux_1,'rest_1 is too high: lower it.');
    k_I = (flux_1-k_r1*rest_1)/rest_1^2;
else
    k_I = kcat_I*E_max/(KM_I*KM_I);
end
p1_ref = (-k_r1+sqrt(k_r1^2+4*k_I*flux_1))/(2*k_I);      % resting m_F = resting m_d1

% ---- Differentiator 2 (input: m_d1) ----
k_r2  = 1/tau_r2;
k_Sr_2 = 1/tau_d2;                       % m_S2 -> m_N2
k_Fr_2 = k_r2;   k_Nr_2 = k_r2;          % removal of m_F2 and of m_N2
flux_2 = k_F_2*p1_ref;                   % resting production of each rail of D2
m_S2_ref = k_S_2*p1_ref/k_Sr_2;
if ideal_canceler
    assert(k_r2*rest_2 < flux_2,'rest_2 is too high for the resting m_d1: lower it.');
    k_I_2 = (flux_2-k_r2*rest_2)/rest_2^2;
else
    k_I_2 = kcat_I_2*E_max/(KM_I_2*KM_I_2);
end
p2_ref = (-k_r2+sqrt(k_r2^2+4*k_I_2*flux_2))/(2*k_I_2);  % resting m_F2 = resting m_N2

% ---- Enzyme concentrations, from k = kcat*[E]/K_M ----
names_all = {'r_S';'r_Sr';'r_F';'r_Fr';'r_I';'r_S_2';'r_Sr_2';'r_F_2';'r_Fr_2';'r_Nr_2 (new)';'r_I_2'};
E_all = [k_S*KM_S/kcat_S; k_Sr*KM_Sr/kcat_Sr; k_F*KM_F/kcat_F; k_Fr*KM_Fr/kcat_Fr; k_I*KM_I^2/kcat_I; ...
         k_S_2*KM_S_2/kcat_S_2; k_Sr_2*KM_Sr_2/kcat_Sr_2; k_F_2*KM_F_2/kcat_F_2; k_Fr_2*KM_Fr_2/kcat_Fr_2; ...
         k_Nr_2*KM_Fr_2/kcat_Fr_2; k_I_2*KM_I_2^2/kcat_I_2];
k_all = [k_S;k_Sr;k_F;k_Fr;k_I;k_S_2;k_Sr_2;k_F_2;k_Fr_2;k_Nr_2;k_I_2];
reaction_parameters = table(names_all,k_all,1e3*E_all, ...
    'VariableNames',{'Reaction','k_per_s_or_per_mM_s','Enzyme_uM'});
disp(reaction_parameters); %[output:12b0292c]
for i = find(E_all > E_max).' %[output:group:4b2cf8f2]
    warning('%s needs %.3g uM, above the limit of %.3g uM.',names_all{i},1e3*E_all(i),1e3*E_max); %[output:8a26ec50] %[output:95732b49]
end %[output:group:4b2cf8f2]
fprintf('Rest: m_S %.3g, m_F = m_d1 %.3g, m_S2 %.3g, m_F2 = m_N2 %.3g mM\n',m_S_ref,p1_ref,m_S2_ref,p2_ref); %[output:5bed8393]

% ---- Counter ----
K_gate = gate_factor*p2_ref;
k_I_supply = 1/tau_I_supply;
g_ref = p2_ref/(K_gate+p2_ref);
E_Cp = (count_step/pulse_time)/kcat_Cp;                  V_Cp = kcat_Cp*E_Cp;
E_Cr = min(E_max,k_I_supply*0.5*m_I_base/(kcat_Cr*0.5*m_I_base/(KM_Cr+0.5*m_I_base)));   V_Cr = kcat_Cr*E_Cr;
I_balance = @(x) k_I_supply*(m_I_base-x)-V_Cr*g_ref*x/(KM_Cr+x)-V_Cp*g_ref;
m_I_ref = fzero(I_balance,[0 m_I_base]);
E_Cg = KM_Cg_c/(tau_reset*kcat_Cg*(m_I_ref/(KM_Cg_I+m_I_ref)));   V_Cg = kcat_Cg*E_Cg;
m_c_ref = KM_Cg_c*V_Cp*g_ref/(V_Cg*m_I_ref/(KM_Cg_I+m_I_ref)-V_Cp*g_ref);
fprintf('Counter: K_gate %.3g mM; enzymes r_c %.3g, r_I1 %.3g, r_I2 %.3g uM\n',K_gate,1e3*E_Cp,1e3*E_Cg,1e3*E_Cr); %[output:32da4421]

% Block 0 supplies what r_S and r_F withdraw from m_in.
j_S_ref = k_S*m_in_target;  j_F_ref = k_F*m_in_target;
%%
%[text] ## 5. Block 0: design concentrations, buffered cosubstrates and capacities
%[text] Concentration targets \[mM\] and turnover numbers are illustrative, not measurements.
tau_B0   = 30;                                   % response time of each Block 0 pool [s]
pool_ref = (j_S_ref+j_F_ref)*tau_B0/1.1;         % reference concentration that gives tau_B0
cAMP_ref = pool_ref; AMP_ref = pool_ref; adn_ref = pool_ref; r1p_ref = pool_ref; uri_ref = pool_ref;
K_EV_AC = 10*vesicles(row,1);            % activation constant in DATASET EV units, not mM
m_ATP_B0 = 2; m_Pi_B0 = 1; m_uracil_B0 = 0.05; m_dUTP_B0 = 0.05;
Km_ADNCYC_ATP = 0.2;
Km_PDE1_cAMP = 10*cAMP_ref;
Km_NTD7_AMP = 10*AMP_ref;
Km_PUNP1_adn = 10*adn_ref;    Km_PUNP1_Pi = 0.1;
Km_PYNP2r_r1p = 10*r1p_ref;   Km_PYNP2r_uracil = 0.005;
Km_r1156_uri = 10*uri_ref;    Km_r1156_dUTP = 0.005;
kcat_ADNCYC = 100; kcat_PDE1 = 100; kcat_NTD7 = 100;
kcat_PUNP1 = 100; kcat_PYNP2r = 100; kcat_r1156 = 100;

% Buffered cosubstrates enter as constant saturation fractions.
ATP_fraction    = m_ATP_B0/(Km_ADNCYC_ATP+m_ATP_B0);
Pi_fraction     = m_Pi_B0/(Km_PUNP1_Pi+m_Pi_B0);
uracil_fraction = m_uracil_B0/(Km_PYNP2r_uracil+m_uracil_B0);
dUTP_fraction   = m_dUTP_B0/(Km_r1156_dUTP+m_dUTP_B0);

% The supply of UMP equals what r_S and r_F withdraw at m_in_target.
J_B0_ref = j_S_ref+j_F_ref;
EV_activity_ref = vesicles(row,1)/(K_EV_AC+vesicles(row,1));
V_ADNCYC = J_B0_ref/(EV_activity_ref*ATP_fraction);
V_PDE1   = J_B0_ref/(cAMP_ref/(Km_PDE1_cAMP+cAMP_ref));
V_NTD7   = J_B0_ref/(AMP_ref/(Km_NTD7_AMP+AMP_ref));
V_PUNP1  = J_B0_ref/((adn_ref/(Km_PUNP1_adn+adn_ref))*Pi_fraction);
V_PYNP2r = J_B0_ref/((r1p_ref/(Km_PYNP2r_r1p+r1p_ref))*uracil_fraction);
V_r1156  = J_B0_ref/((uri_ref/(Km_r1156_uri+uri_ref))*dUTP_fraction);

block0_parameters = table( ...
    {'ADNCYC (assumed EV control)';'PDE1';'NTD7';'PUNP1';'PYNP2r (reverse)';'r1156'}, ...
    [Km_ADNCYC_ATP;Km_PDE1_cAMP;Km_NTD7_AMP;Km_PUNP1_adn;Km_PYNP2r_r1p;Km_r1156_uri], ...
    [kcat_ADNCYC;kcat_PDE1;kcat_NTD7;kcat_PUNP1;kcat_PYNP2r;kcat_r1156], ...
    1e3*[V_ADNCYC/kcat_ADNCYC;V_PDE1/kcat_PDE1;V_NTD7/kcat_NTD7; ...
         V_PUNP1/kcat_PUNP1;V_PYNP2r/kcat_PYNP2r;V_r1156/kcat_r1156], ...
    [V_ADNCYC;V_PDE1;V_NTD7;V_PUNP1;V_PYNP2r;V_r1156], ...
    'VariableNames',{'Reaction','Km_mM','kcat_per_s','Enzyme_uM','Vmax_mM_per_s'});
disp(block0_parameters); %[output:519d09fc]
%%
%[text] ## 6. Simulation (analysed distance) from the rest state
% Each step: (1) production and first-order removal with explicit Euler,
% giving trial values P and Q of the two rails; (2) the canceler applied
% implicitly. With D = P - Q (which the canceler does not change), the new
% P solves   P_new = P - dt*k*P_new*(P_new - D),   a quadratic with one
% positive root; then Q_new = P_new - D. Stable for any canceler strength.
EV = vesicles(row,:).';
m_cAMP = cAMP_ref*ones(N,1); m_AMP = AMP_ref*ones(N,1); m_adn = adn_ref*ones(N,1);
m_r1p = r1p_ref*ones(N,1);   m_uri = uri_ref*ones(N,1); m_in = m_in_target*ones(N,1);
m_S = m_S_ref*ones(N,1);     m_F = p1_ref*ones(N,1);    m_d1 = p1_ref*ones(N,1);
m_S2 = m_S2_ref*ones(N,1);   m_F2 = p2_ref*ones(N,1);   m_N2 = p2_ref*ones(N,1);
m_c = m_c_ref*ones(N,1);     m_I = m_I_ref*ones(N,1);   gate = g_ref*ones(N,1);

for n = 1:N-1
    dt = t(n+1)-t(n);
    % Block 0
    v_ADNCYC = V_ADNCYC*EV(n)/(K_EV_AC+EV(n))*ATP_fraction;              % ATP -> cAMP
    v_PDE1   = V_PDE1*m_cAMP(n)/(Km_PDE1_cAMP+m_cAMP(n));            % cAMP -> AMP
    v_NTD7   = V_NTD7*m_AMP(n)/(Km_NTD7_AMP+m_AMP(n));               % AMP -> adenosine
    v_PUNP1  = V_PUNP1*m_adn(n)/(Km_PUNP1_adn+m_adn(n))*Pi_fraction;     % adenosine -> ribose-1-P
    v_PYNP2r = V_PYNP2r*m_r1p(n)/(Km_PYNP2r_r1p+m_r1p(n))*uracil_fraction;   % ribose-1-P -> uridine
    v_r1156 = V_r1156*m_uri(n)/(Km_r1156_uri+m_uri(n))*dUTP_fraction;   % uridine -> UMP

    m_cAMP(n+1) = m_cAMP(n)+dt*(v_ADNCYC-v_PDE1);
    m_AMP(n+1)  = m_AMP(n) +dt*(v_PDE1-v_NTD7);
    m_adn(n+1)  = m_adn(n) +dt*(v_NTD7-v_PUNP1);
    m_r1p(n+1)  = m_r1p(n) +dt*(v_PUNP1-v_PYNP2r);
    m_uri(n+1)  = m_uri(n) +dt*(v_PYNP2r-v_r1156);
    m_in(n+1)   = m_in(n)  +dt*(v_r1156-(k_S+k_F)*m_in(n));

    % ---- Differentiator 1 ----
    m_S(n+1) = m_S(n)+dt*(k_S*m_in(n)-k_Sr*m_S(n));                    % delay pool
    P = m_F(n) +dt*(k_F*m_in(n)-k_Fr*m_F(n));                          % direct rail
    Q = m_d1(n)+dt*(k_Sr*m_S(n)-(k_F_2+k_S_2)*m_d1(n));                % delayed rail; removal = load of D2
    D = P-Q;                                                           % canceler, implicit over dt
    qb = 1-dt*k_I*D;  qd = sqrt(qb^2+4*dt*k_I*P);
    if qb > 0
        P = 2*P/(qb+qd);
    else
        P = (qd-qb)/(2*dt*k_I);
    end
    m_F(n+1) = max(P,0);  m_d1(n+1) = max(P-D,0);

    % ---- Differentiator 2 (fed by the m_d1 it consumes) ----
    m_S2(n+1) = m_S2(n)+dt*(k_S_2*m_d1(n)-k_Sr_2*m_S2(n));             % delay pool
    P = m_F2(n)+dt*(k_F_2*m_d1(n)-k_Fr_2*m_F2(n));                     % direct rail = m_d2
    Q = m_N2(n)+dt*(k_Sr_2*m_S2(n)-k_Nr_2*m_N2(n));                    % delayed rail
    D = P-Q;                                                           % canceler, implicit over dt
    qb = 1-dt*k_I_2*D;  qd = sqrt(qb^2+4*dt*k_I_2*P);
    if qb > 0
        P = 2*P/(qb+qd);
    else
        P = (qd-qb)/(2*dt*k_I_2);
    end
    m_F2(n+1) = max(P,0);  m_N2(n+1) = max(P-D,0);

    % ---- Counter (activated by m_d2 = m_F2) ----
    gate(n) = m_F2(n)/(K_gate+m_F2(n));
    v_Cp = V_Cp*gate(n);                                               % r_c : -> m_c
    v_Cg = V_Cg*m_c(n)/(KM_Cg_c+m_c(n))*m_I(n)/(KM_Cg_I+m_I(n));       % r_I1: m_c + m_I -> products
    v_Cr = V_Cr*gate(n)*m_I(n)/(KM_Cr+m_I(n));                         % r_I2: m_I -> products
    m_c(n+1) = m_c(n)+dt*(v_Cp-v_Cg);
    m_I(n+1) = m_I(n)+dt*(k_I_supply*(m_I_base-m_I(n))-v_Cr-v_Cg);

    pools = [m_in(n+1),m_S(n+1),m_F(n+1),m_d1(n+1),m_S2(n+1),m_F2(n+1),m_N2(n+1),m_c(n+1),m_I(n+1)];
    assert(all(isfinite(pools)) && all(pools >= 0),'Invalid step at n = %d; reduce dt0.',n);
end
gate(N) = m_F2(N)/(K_gate+m_F2(N));
m_d2 = m_F2;
%%
%[text] ## 7. Diagnostics
% The identity of Eq. (8): m_F - m_d1 against w_1*(m_in - delayed m_in), smoothed with tau_r1.
x_del = m_in;  ideal_1 = zeros(N,1);                     % reference computed by plain filtering
for n = 1:N-1
    x_del(n+1)   = x_del(n)+dt0*(m_in(n)-x_del(n))/tau_d1;
    ideal_1(n+1) = ideal_1(n)+dt0*(w_1*(m_in(n)-x_del(n))-ideal_1(n))/tau_r1;
end
diff_1 = m_F-m_d1;
fprintf('\nD1: m_F - m_d1 against the ideal weighted subtraction: largest gap %.3g mM (signal up to %.3g mM)\n', ... %[output:group:6a3cf7fb] %[output:176a7ccd]
    max(abs(diff_1-ideal_1)),max(abs(ideal_1))); %[output:group:6a3cf7fb] %[output:176a7ccd]
fprintf('D1 output m_d1: rest %.3g, peak %.3g at %.3g min, last %.3g mM;  m_F peak %.3g mM\n', ... %[output:group:9d700087] %[output:2ef7f06e]
    m_d1(1),max(m_d1),t(find(m_d1 == max(m_d1),1))/60,m_d1(end),max(m_F)); %[output:group:9d700087] %[output:2ef7f06e]
fprintf('D2 output m_d2: rest %.3g, peak %.3g at %.3g min, last %.3g mM;  m_N2 peak %.3g mM\n', ... %[output:group:386b8bdb] %[output:4d485994]
    m_d2(1),max(m_d2),t(find(m_d2 == max(m_d2),1))/60,m_d2(end),max(m_N2)); %[output:group:386b8bdb] %[output:4d485994]
fprintf('Counter: activation rest %.3g, largest %.3g;  m_c rest %.3g, peak %.3g at %.3g min, last %.3g mM\n', ... %[output:group:736dd564] %[output:80b88345]
    gate(1),max(gate),m_c(1),max(m_c),t(find(m_c == max(m_c),1))/60,m_c(end)); %[output:group:736dd564] %[output:80b88345]
fprintf('Largest pool / K_M (first-order kinetics need << 1): m_S %.2g, m_F %.2g, m_d1 %.2g, m_S2 %.2g, m_F2 %.2g\n', ... %[output:group:50838075] %[output:865a6422]
    max(m_S)/KM_Sr,max(m_F)/min(KM_Fr,KM_I),max(m_d1)/min([KM_I KM_F_2 KM_S_2]),max(m_S2)/KM_Sr_2,max(m_F2)/min(KM_Fr_2,KM_I_2)); %[output:group:50838075] %[output:865a6422]
