%[text] ## 8. Figures
% 1. Input.
figure; %[output:032a8a72]
plot(t/60,m_in,'LineWidth',2); grid on; %[output:032a8a72]
xlabel('Time [min]'); ylabel('UMP: m_{in} [mM]'); set(gca,'FontSize',fontsize+4); %[output:032a8a72]

% 2. Differentiator 1: the two rails, and the falling slope of the input.
figure; %[output:46cdacb9]
yyaxis left;  plot(t/60,[m_d1,m_F],'LineWidth',2); ylabel('Concentration [mM]'); %[output:46cdacb9]
yyaxis right; plot(t/60,-gradient(m_in,t),':','LineWidth',1.5); ylabel('-dm_{in}/dt [mM/s]'); %[output:46cdacb9]
xlabel('Time [min]'); xlim([0,min(150,t(end)/60)]); grid on; %[output:46cdacb9]
legend('m_{d1} (delayed rail, output)','m_F (direct rail)','input falling slope','Location','best'); %[output:46cdacb9]
set(gca,'FontSize',fontsize); %[output:46cdacb9]

% 3. Differentiator 2: the two rails, and the slope of m_d1.
figure; %[output:58aabddf]
yyaxis left;  plot(t/60,[m_d2,m_N2],'LineWidth',2); ylabel('Concentration [mM]'); %[output:58aabddf]
yyaxis right; plot(t/60,gradient(m_d1,t),':','LineWidth',1.5); ylabel('dm_{d1}/dt [mM/s]'); %[output:58aabddf]
xlabel('Time [min]'); xlim([0,min(150,t(end)/60)]); grid on; %[output:58aabddf]
legend('m_{d2} (direct rail, output)','m_{N2} (delayed rail)','slope of m_{d1}','Location','best'); %[output:58aabddf]
set(gca,'FontSize',fontsize); %[output:58aabddf]

% 4. Check of Eq. (8): difference of the rails against the ideal subtraction.
figure; %[output:0d68827a]
plot(t/60,diff_1,'LineWidth',2); hold on; plot(t/60,ideal_1,'--','LineWidth',1.5); grid on; %[output:0d68827a]
xlabel('Time [min]'); ylabel('[mM]'); xlim([0,min(150,t(end)/60)]); %[output:0d68827a]
legend('m_F - m_{d1}','w_1 (m_{in} - delayed m_{in})','Location','best'); set(gca,'FontSize',fontsize); %[output:0d68827a]

% 5. Counter.
figure; %[output:3097fd37]
yyaxis left;  plot(t/60,m_c,'LineWidth',2); ylabel('m_c [mM]'); %[output:3097fd37]
yyaxis right; plot(t/60,gate,'--','LineWidth',1.5); ylabel('activation by m_{d2}'); ylim([0 1]); %[output:3097fd37]
xlabel('Time [min]'); xlim([0,min(150,t(end)/60)]); grid on; %[output:3097fd37]
legend('m_c (counter)','activation of r_c','Location','best'); set(gca,'FontSize',fontsize); %[output:3097fd37]
